/** One local 16x16 H.264 frame, generated and fully decoded with FFmpeg; tests never download media. */
import { createHash } from 'node:crypto';
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

export const VIDEO_ONE = '7100000000000000001';
export const VIDEO_TWO = '7100000000000000002';
export const VIDEO_THREE = '7100000000000000003';
export const videoURL = id => 'https://www.douyin.com/video/' + id;
export const digest = bytes => createHash('sha256').update(bytes).digest('hex');
export const MP4 = Buffer.from('', 'base64');

export function selectedVideo(url) {
  const parsed = new URL(url);
  return /\/(?:share\/)?video\/(\d{10,25})/.exec(parsed.pathname)?.[1] ?? parsed.searchParams.get('modal_id');
}

/** The injected transport copies real local media; production owns codec verification and native acquisition. */
export async function mediaReceipt(agent, url, extra = {}) {
  const id = selectedVideo(url);
  if (!id) throw new Error('Fixture requires a selected canonical video ID');
  const directory = join(agent.session.header.cwd, 'source', 'media', 'douyin');
  await mkdir(directory, { recursive: true });
  const path = join(directory, id + '.mp4'), receipt = path + '.source.json';
  await writeFile(path, MP4, { mode: 0o600 });
  const result = { status: 'downloaded', path, receipt, source: videoURL(id), bytes: MP4.byteLength,
    sha256: digest(MP4), duration_seconds: 1, width: 16, height: 16, full_decode_verified: true, ...extra };
  await writeFile(receipt, JSON.stringify(result, null, 2) + '\n', { mode: 0o600 });
  return result;
}
